@startuml

class Location {
  + Address : string
}

abstract class Vehicle {
  + VehicleNumber : string
}

class Truck {
  + Weight : int
}

class Car {
  + Seats : int
}

class Van {}

class Driver {
  + FirstName : string
  + LastName : string
}

class Order {
  + Origin : Location
  + Destination : Location
  + AssignedDriver : Driver
  + ExecutionDate : date
}

Location "1" -- "*" Vehicle
Vehicle "0..1" -- "1" Driver
Driver "1" -- "0..1" Order

@enduml

